                (n - 1 - r, c), (r, n - 1 - c),
                (n - 1 - r, n - 1 - c),
                (n - 1 - c, n - 1 - r),
                (c, n - 1 - r), (n - 1 - c, r),
            }
            known = [grid[a][b] for a, b in orbit if grid[a][b] != 2]
            if known:
                out[r][c] = Counter(known).most_common(1)[0][0]
